-- 5. Admissions and Dependent Systems

-- 6. Update patients who died during an admission
UPDATE patient SET life_status = 'Deceased'
WHERE patient_id IN (
    SELECT a.patient_id FROM admission a
    JOIN discharge_record d ON d.admission_id = a.admission_id
    WHERE d.discharge_status = 'Deceased'
);

COMMIT;
